/// <summary>
///     The <c>AVAPriceDiscAdmTableFrm_Extension</c> class is the extension for <c>PriceDiscAdmTable</c>
/// </summary>
[ExtensionOf(formStr(PriceDiscAdmTable))]
final class AVAPriceDiscAdmTableFrm_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    next init();

    this.avaInitFromArgs(this.args());
    this.avaModifyRangesFromArgs(this.args());
}

/// <summary>
///     AVA <c>avaInitFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
protected void avaInitFromArgs(Args _args)
{
    FormComboBoxControl             locFCBC;
    Common                          locCommon;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;
    PriceDiscAdmTable               locPriceDiscAdmTable;
    str                             locLookupValue;

    locFCBC = this.design().controlName(formControlStr(PriceDiscAdmTable, allOpenPosted));

    if(_args.caller() && _args.caller().name() == formStr(AVAPriceIncreaseTable))
    {
        locFCBC.selection(AllOpenPosted::All);
        locFCBC.selectionChange();

        locCommon = _args.record();
        if(locCommon.TableId == tableNum(AVAPriceIncreasePriceDiscGroup))
        {
            locAVAPriceIncreasePriceDiscGroup = locCommon;
            locPriceDiscAdmTable = PriceDiscAdmTable::find(locAVAPriceIncreasePriceDiscGroup.JournalNum);
        }
        else if(locCommon.TableId == tableNum(PriceDiscAdmTable))
        {
            locPriceDiscAdmTable = locCommon;
        }
    }
    else if(_args.caller() && _args.caller().name() == formStr(PriceDiscAdmTable))
    {
        locCommon       = _args.record();
        locLookupValue  = _args.lookupValue();

        if(locLookupValue)
        {
            locPriceDiscAdmTable    = PriceDiscAdmTable::find(locLookupValue);
            callerPriceDiscAdmTable = locPriceDiscAdmTable;
            this.args().record(callerPriceDiscAdmTable);
            locFCBC.selection(AllOpenPosted::All);
            locFCBC.selectionChange();
        }
    }
}

/// <summary>
///     AVA <c>avaModifyRangesFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
protected void avaModifyRangesFromArgs(Args _args)
{
    Query                   locQuery;
    QueryBuildDataSource    locQBDsPriceDiscAdmTable;
    QueryBuildRange         locQueryBuildRange;

    if(callerPriceDiscAdmTable.RecId)
    {
        locQuery                    = priceDiscAdmTable_ds.query();
        locQBDsPriceDiscAdmTable    = locQuery.dataSourceTable(tablenum(PriceDiscAdmTable));
        locQueryBuildRange          = SysQuery::findOrCreateRange(locQBDsPriceDiscAdmTable, fieldNum(PriceDiscAdmTable, JournalNum));
        locQueryBuildRange.value(queryValue(callerPriceDiscAdmTable.JournalNum));
    }

}
